    html.append(f'''<section class="page"><div class="head"><div class="num">{x['n']}</div><div><div class="kicker">{esc(x['cluster'])} · phần học sâu</div><div class="title">{esc(x['title'])}</div></div></div><div class="grid2"><div class="box"><h3>4. Công thức / mô hình trung tâm</h3><div class="formula">{esc(x['formula'])}</div></div><div class="box"><h3>5. Nhà đầu tư cần hiểu</h3><p>{esc(x['investor'])}</p></div></div><div class="box"><h3>6. Không nên hiểu sai</h3><p>{esc(x['wrong'])}</p></div><div class="take"><b>Takeaway của video:</b> {esc(x['investor'])}</div><div class="footer"><span>MIT 18.642 · Video {x['n']}</span><span>Trang 2/2</span></div></section>''')
    md.append(f"\n## {x['n']}. {x['title']}\n\n### Video này dạy gì\n{x['core']}\n\n### Ý phải nắm\n"+'\n'.join(f"- {v}" for v in x['learn'])+"\n\n### Diễn giải\n"+'\n'.join(f"- {v}" for v in x['details'])+f"\n\n### Công thức\n```\n{x['formula']}\n```\n\n### Nhà đầu tư cần hiểu\n{x['investor']}\n\n### Không nên hiểu sai\n{x['wrong']}\n")
