('Bảng công thức cốt lõi', [('PV / Discounting','PV=CF/(1+r)^t'),('Duration','ΔP/P≈-D×Δy'),('OLS','y=Xβ+ε'),('Portfolio variance','wᵀΣw'),('Black-Scholes inputs','S,K,T,r,σ'),('GBM','dS=μSdt+σSdW')]),
