('Checklist đọc bài như nhà đầu tư', [('Horizon','Mọi nhận định phải có khung thời gian'),('Probability','Không dùng ngôn ngữ chắc chắn'),('Payoff','Biết lời/lỗ trung bình'),('Risk','Drawdown, tail risk, liquidity'),('Validation','OOS/walk-forward'),('Sizing','Tỷ trọng theo risk')]),
